={{ { query: "query Finales($where: solicitud_proveedores_bool_exp!) {
  solicitud_proveedores(where: $where, limit: 201) {
    solicitud_id proveedor_id estado_respuesta detalle_respuesta considerado
  }
}", variables: { where: { estado_respuesta: { _eq: 'envio_cotizacion' }, considerado: { _eq: true }, ...($json.solicitud_id ? { solicitud_id: { _eq: $json.solicitud_id } } : {}) } } } }}

